from __future__ import annotations

from pathlib import Path

ROOT = Path(__file__).resolve().parents[1] if Path(__file__).parent.name == 'scripts' else Path.cwd()
if (ROOT / 'src' / 'weall').exists():
    REPO = ROOT
elif (ROOT / 'Weall-Protocol' / 'src' / 'weall').exists():
    REPO = ROOT / 'Weall-Protocol'
else:
    raise SystemExit('cannot locate Weall-Protocol root')


def text(path: str) -> str:
    return (REPO / path).read_text(encoding='utf-8')


def write(path: str, data: str) -> None:
    (REPO / path).write_text(data, encoding='utf-8')


def replace_once(data: str, old: str, new: str, label: str) -> str:
    count = data.count(old)
    if count != 1:
        raise SystemExit(f'{label}: expected exactly one match, found {count}')
    return data.replace(old, new, 1)


