new_ack = '''def process_inbound_ack(state: HandshakeState, msg: PeerHelloAck) -> PeerHello | None:\n    cfg = state.config\n    if cfg.require_identity:\n        corr_id = str(getattr(msg.header, "corr_id", "") or "").strip()\n        expected_corr = str(state.outbound_corr_id or "").strip()\n        if not expected_corr or corr_id != expected_corr:\n            raise HandshakeRejected("hello_ack_corr_id_mismatch")\n        if not msg.ok:\n            state.status = "REJECTED"\n            state.session_id = None\n            state.last_error = str(msg.reason or "handshake_rejected")\n            raise HandshakeRejected(state.last_error)\n        _check_protocol_profile(cfg, protocol_version=getattr(msg, "protocol_version", None), protocol_profile_hash=getattr(msg, "protocol_profile_hash", None))\n        _check_validator_metadata(cfg, validator_epoch=getattr(msg, "validator_epoch", None), validator_set_hash=getattr(msg, "validator_set_hash", None), bft_enabled=getattr(msg, "bft_enabled", None))\n        _check_genesis_bootstrap_metadata(cfg, genesis_bootstrap_profile_hash=getattr(msg, "genesis_bootstrap_profile_hash", None), genesis_bootstrap_enabled=getattr(msg, "genesis_bootstrap_enabled", None), genesis_bootstrap_mode=getattr(msg, "genesis_bootstrap_mode", None))\n        if str(getattr(msg, "recipient_peer_id", "") or "").strip() != str(cfg.peer_id).strip():\n            raise HandshakeRejected("hello_ack_recipient_mismatch")\n        phase = str(getattr(msg, "phase", "") or "").strip().lower()\n        challenge = str(getattr(msg, "challenge", "") or "").strip()\n        if state.status == "SENT_HELLO":\n            if phase != "challenge" or not challenge:\n                raise HandshakeRejected("hello_ack_challenge_missing")\n            state.outbound_challenge = challenge\n            response = _build_challenge_response(state)\n            state.status = "SENT_CHALLENGE_RESPONSE"\n            state.last_error = None\n            return response\n        if state.status == "SENT_CHALLENGE_RESPONSE":\n            if phase != "final":\n                raise HandshakeRejected("hello_ack_final_missing")\n            if not challenge or challenge != str(state.outbound_challenge or "").strip():\n                raise HandshakeRejected("hello_ack_final_challenge_mismatch")\n            state.status = "ESTABLISHED"\n            state.session_id = _new_session_id()\n            state.last_error = None\n            return None\n        raise HandshakeError("unexpected_hello_ack")\n    if state.status not in {"SENT_HELLO"}:\n        raise HandshakeError("unexpected_hello_ack")\n    if not msg.ok:\n        state.status = "REJECTED"\n        state.session_id = None\n        state.last_error = str(msg.reason or "handshake_rejected")\n        raise HandshakeRejected(state.last_error)\n    _check_protocol_profile(state.config, protocol_version=getattr(msg, "protocol_version", None), protocol_profile_hash=getattr(msg, "protocol_profile_hash", None))\n    _check_validator_metadata(state.config, validator_epoch=getattr(msg, "validator_epoch", None), validator_set_hash=getattr(msg, "validator_set_hash", None), bft_enabled=getattr(msg, "bft_enabled", None))\n    _check_genesis_bootstrap_metadata(state.config, genesis_bootstrap_profile_hash=getattr(msg, "genesis_bootstrap_profile_hash", None), genesis_bootstrap_enabled=getattr(msg, "genesis_bootstrap_enabled", None), genesis_bootstrap_mode=getattr(msg, "genesis_bootstrap_mode", None))\n    state.status = "ESTABLISHED"\n    state.session_id = _new_session_id()\n    state.last_error = None\n    return None\n\n'''
