new_methods = '''    def _verify_inbound_hello_identity(self, rec: _PeerRec, hello: PeerHello) -> None:\n        if not self._identity_required():\n            return\n        ledger = self._get_ledger()\n        if ledger is None:\n            raise HandshakeRejected("identity_required_but_no_ledger")\n        ok, reason, account_id, pubkey = verify_peer_hello_identity(\n            hello=hello, ledger=ledger, strict=True, now_ms=_now_ms()\n        )\n        if not ok:\n            raise HandshakeRejected(f"identity_invalid:{reason}")\n        hs = rec.router.handshake\n        if hs.status == "AWAITING_CHALLENGE_RESPONSE":\n            if str(getattr(hello.header, "corr_id", "") or "").strip() != str(hs.inbound_corr_id or "").strip():\n                raise HandshakeRejected("identity_invalid:challenge_corr_id_mismatch")\n            if str(getattr(hello, "nonce", "") or "").strip() != str(hs.inbound_challenge or "").strip():\n                raise HandshakeRejected("identity_invalid:challenge_response_mismatch")\n            if rec.pending_identity_account and rec.pending_identity_account != account_id:\n                raise HandshakeRejected("identity_invalid:account_changed_during_handshake")\n            if rec.pending_identity_pubkey and rec.pending_identity_pubkey != pubkey:\n                raise HandshakeRejected("identity_invalid:pubkey_changed_during_handshake")\n            rec.pending_session_identity_verified = True\n        rec.pending_identity_account = account_id\n        rec.pending_identity_pubkey = pubkey\n\n    def _verify_inbound_ack_identity(self, rec: _PeerRec, ack: Any) -> None:\n        if not self._identity_required():\n            return\n        ledger = self._get_ledger()\n        if ledger is None:\n            raise HandshakeRejected("identity_required_but_no_ledger")\n        hs = rec.router.handshake\n        ok, reason, account_id, pubkey = verify_peer_hello_ack_identity(\n            ack=ack, ledger=ledger, expected_recipient_peer_id=str(self.cfg.peer_id or "").strip(),\n            expected_corr_id=str(hs.outbound_corr_id or "").strip(), now_ms=_now_ms()\n        )\n        if not ok:\n            raise HandshakeRejected(f"identity_ack_invalid:{reason}")\n        if rec.pending_identity_account and rec.pending_identity_account != account_id:\n            raise HandshakeRejected("identity_ack_invalid:account_changed_during_handshake")\n        if rec.pending_identity_pubkey and rec.pending_identity_pubkey != pubkey:\n            raise HandshakeRejected("identity_ack_invalid:pubkey_changed_during_handshake")\n        rec.pending_identity_account = account_id\n        rec.pending_identity_pubkey = pubkey\n        if str(getattr(ack, "phase", "") or "").strip().lower() == "final":\n            rec.pending_session_identity_verified = True\n\n    def _finalize_authenticated_session_identity(self, rec: _PeerRec) -> None:\n        if not self._identity_required():\n            return\n        if not rec.pending_session_identity_verified:\n            raise HandshakeRejected("identity_session_challenge_not_verified")\n        if not rec.pending_identity_account or not rec.pending_identity_pubkey:\n            raise HandshakeRejected("identity_session_binding_missing")\n        rec.identity_ok = True\n        rec.identity_account = rec.pending_identity_account\n        rec.identity_pubkey = rec.pending_identity_pubkey\n        self._bind_authenticated_peer_security(rec, session_bound=True)\n\n'''
s = s[:start] + new_methods + s[end+1:]
anchor = '''        # BFT identity gate for votes\n        if getattr(msg.header, "type", None) == MsgType.BFT_VOTE:\n'''
insert = '''        if getattr(msg.header, "type", None) == MsgType.PEER_HELLO_ACK:\n            try:\n                self._verify_inbound_ack_identity(rec, msg)\n            except HandshakeRejected:\n                self._strike(rec, int(self.peer_policy.strike_handshake_rejected))\n                if int(self.peer_policy.fast_ban_mismatch_ms) > 0:\n                    self._ban(rec, cooldown_ms=int(self.peer_policy.fast_ban_mismatch_ms))\n                return\n\n'''
if anchor not in s:
    raise SystemExit('node BFT gate anchor missing')
s = s.replace(anchor, insert + anchor, 1)
s = replace_once(s, '''        established_after_route = self._peer_is_established(rec)\n        if established_after_route and int(rec.established_at_ms) <= 0:\n            rec.established_at_ms = int(now)\n\n        # Send response if any\n''', '''        established_after_route = self._peer_is_established(rec)\n        if established_after_route:\n            if self._identity_required() and not rec.identity_ok:\n                try:\n                    self._finalize_authenticated_session_identity(rec)\n                except HandshakeRejected:\n                    rec.router.handshake.status = "REJECTED"\n                    rec.router.handshake.session_id = None\n                    self._strike(rec, int(self.peer_policy.strike_handshake_rejected))\n                    return\n            if int(rec.established_at_ms) <= 0:\n                rec.established_at_ms = int(now)\n\n        # Send response if any\n''', 'node finalize identity after route')
write(p, s)

p = 'tests/test_net_bft_identity_gate.py'
s = text(p)
s = replace_once(s, 'import hashlib\n', 'import hashlib\nimport time\n', 'bft identity import time')
s = replace_once(s, '''def _cfg() -> NetConfig:\n    return NetConfig(chain_id="test", schema_version="1", tx_index_hash="deadbeef", peer_id="local")\n''', '''def _cfg() -> NetConfig:\n    pubkey, _sk = deterministic_mldsa_keypair(label="local")\n    return NetConfig(\n        chain_id="test", schema_version="1", tx_index_hash="deadbeef", peer_id="local",\n        identity_pubkey=pubkey, identity_privkey=_seed_hex("local")\n    )\n''', 'bft identity strict local cfg')
helper_anchor = 'def _ledger_for_validator(account_id: str, pubkey_hex: str) -> dict:\n'
helper_insert = '''def _complete_inbound_identity_handshake(\n    node: NetNode, *, transport_peer: str, account_id: str, pubkey: str, label: str\n) -> None:\n    corr_id = f"corr-{label}"\n    hdr = WireHeader(\n        type=MsgType.PEER_HELLO, chain_id="test", schema_version="1", tx_index_hash="deadbeef",\n        sent_ts_ms=int(time.time() * 1000), corr_id=corr_id\n    )\n    ident = sign_peer_hello_identity(\n        header=hdr, peer_id=account_id, pubkey=pubkey, privkey=_seed_hex(label),\n        agent="weall-node", nonce=corr_id\n    )\n    node._handle_packet(_pkt(transport_peer, PeerHello(header=hdr, peer_id=account_id, agent="weall-node", nonce=corr_id, caps=(), identity=ident)))\n    rec = node._peers[transport_peer]\n    challenge = str(rec.router.handshake.inbound_challenge or "")\n    assert challenge\n    hdr2 = WireHeader(\n        type=MsgType.PEER_HELLO, chain_id="test", schema_version="1", tx_index_hash="deadbeef",\n        sent_ts_ms=int(time.time() * 1000), corr_id=corr_id\n    )\n    ident2 = sign_peer_hello_identity(\n        header=hdr2, peer_id=account_id, pubkey=pubkey, privkey=_seed_hex(label),\n        agent="weall-node", nonce=challenge\n    )\n    node._handle_packet(_pkt(transport_peer, PeerHello(header=hdr2, peer_id=account_id, agent="weall-node", nonce=challenge, caps=(), identity=ident2)))\n    assert rec.router.handshake.is_established()\n    assert rec.identity_ok is True\n\n\n'''
if helper_anchor not in s:
    raise SystemExit('bft identity ledger helper anchor missing')
s = s.replace(helper_anchor, helper_insert + helper_anchor, 1)
old_block = '''    # Handshake hello (with identity)\n    hdr = WireHeader(\n        type=MsgType.PEER_HELLO, chain_id="test", schema_version="1", tx_index_hash="deadbeef"\n    )\n    ident = sign_peer_hello_identity(\n        header=hdr,\n        peer_id="alice",\n        pubkey=pubkey,\n        privkey=_seed_hex("alice"),\n        agent="weall-node",\n        nonce="",\n    )\n    hello = PeerHello(\n        header=hdr, peer_id="alice", agent="weall-node", nonce="", caps=(), identity=ident\n    )\n    node._handle_packet(_pkt("tcp://9.9.9.9:7777", hello))\n'''
new_block = '''    _complete_inbound_identity_handshake(\n        node, transport_peer="tcp://9.9.9.9:7777", account_id="alice", pubkey=pubkey, label="alice"\n    )\n'''
if s.count(old_block) != 2:
    raise SystemExit(f'bft identity expected 2 legacy handshake blocks, found {s.count(old_block)}')
s = s.replace(old_block, new_block)
write(p, s)

p = 'tests/test_p0_05_f001_mutual_peer_auth.py'
if (REPO / p).exists():
    raise SystemExit(f'{p} already exists')
write(p, '''from __future__ import annotations\n\nimport hashlib\nimport time\n\nimport pytest\n\nfrom weall.net.handshake import HandshakeConfig, HandshakeRejected, HandshakeState, begin_outbound_handshake, process_inbound_ack, process_inbound_hello\nfrom weall.net.messages import PeerHelloAck\nfrom weall.net.peer_identity import verify_peer_hello_ack_identity, verify_peer_hello_identity\nfrom weall.testing.sigtools import deterministic_mldsa_keypair\n\n\ndef _seed_hex(label: str) -> str:\n    return hashlib.sha256(("weall-test-mldsa:" + label).encode("utf-8")).digest().hex()\n\n\ndef _cfg(label: str) -> HandshakeConfig:\n    pubkey, _ = deterministic_mldsa_keypair(label=label)\n    return HandshakeConfig(chain_id="test", schema_version="1", tx_index_hash="deadbeef", peer_id=label, identity_pubkey=pubkey, identity_privkey=_seed_hex(label), require_identity=True)\n\n\ndef _ledger() -> dict:\n    out = {"accounts": {}}\n    for label in ("alice", "bob"):\n        pubkey, _ = deterministic_mldsa_keypair(label=label)\n        out["accounts"][label] = {"keys": {pubkey: {"active": True}}, "devices": {"node:0": {"active": True, "device_type": "node"}}}\n    return out\n\n\ndef test_strict_mutual_identity_requires_receiver_challenge_and_both_signed_acks() -> None:\n    ledger = _ledger()\n    alice = HandshakeState(config=_cfg("alice"))\n    bob = HandshakeState(config=_cfg("bob"))\n    hello = begin_outbound_handshake(alice)\n    ok, reason, account, _ = verify_peer_hello_identity(hello=hello, ledger=ledger, strict=True, now_ms=int(time.time() * 1000))\n    assert (ok, reason, account) == (True, "ok", "alice")\n    challenge_ack = process_inbound_hello(bob, hello)\n    assert bob.is_established() is False\n    assert challenge_ack.phase == "challenge" and challenge_ack.challenge\n    ok2, reason2, account2, _ = verify_peer_hello_ack_identity(ack=challenge_ack, ledger=ledger, expected_recipient_peer_id="alice", expected_corr_id=str(hello.header.corr_id), now_ms=int(time.time() * 1000))\n    assert (ok2, reason2, account2) == (True, "ok", "bob")\n    challenge_response = process_inbound_ack(alice, challenge_ack)\n    assert challenge_response is not None and alice.is_established() is False\n    assert challenge_response.nonce == challenge_ack.challenge\n    ok3, reason3, account3, _ = verify_peer_hello_identity(hello=challenge_response, ledger=ledger, strict=True, now_ms=int(time.time() * 1000))\n    assert (ok3, reason3, account3) == (True, "ok", "alice")\n    final_ack = process_inbound_hello(bob, challenge_response)\n    assert bob.is_established() is True\n    assert final_ack.phase == "final" and final_ack.challenge == challenge_ack.challenge\n    ok4, reason4, account4, _ = verify_peer_hello_ack_identity(ack=final_ack, ledger=ledger, expected_recipient_peer_id="alice", expected_corr_id=str(hello.header.corr_id), now_ms=int(time.time() * 1000))\n    assert (ok4, reason4, account4) == (True, "ok", "bob")\n    assert process_inbound_ack(alice, final_ack) is None\n    assert alice.is_established() is True\n    replay_ack = process_inbound_hello(bob, challenge_response)\n    assert replay_ack.ok is False and replay_ack.reason == "unexpected_peer_hello"\n\n\ndef test_strict_ack_rejects_unsigned_wrong_recipient_and_wrong_correlation() -> None:\n    ledger = _ledger()\n    alice = HandshakeState(config=_cfg("alice"))\n    bob = HandshakeState(config=_cfg("bob"))\n    hello = begin_outbound_handshake(alice)\n    ack = process_inbound_hello(bob, hello)\n    unsigned = PeerHelloAck(header=ack.header, peer_id=ack.peer_id, ok=True, caps=ack.caps, server_ts_ms=ack.server_ts_ms, phase=ack.phase, challenge=ack.challenge, recipient_peer_id=ack.recipient_peer_id, identity=None)\n    ok, reason, *_ = verify_peer_hello_ack_identity(ack=unsigned, ledger=ledger, expected_recipient_peer_id="alice", expected_corr_id=str(hello.header.corr_id), now_ms=int(time.time() * 1000))\n    assert ok is False and reason == "missing_pubkey"\n    ok2, reason2, *_ = verify_peer_hello_ack_identity(ack=ack, ledger=ledger, expected_recipient_peer_id="mallory", expected_corr_id=str(hello.header.corr_id), now_ms=int(time.time() * 1000))\n    assert ok2 is False and reason2 == "recipient_peer_id_mismatch"\n    ok3, reason3, *_ = verify_peer_hello_ack_identity(ack=ack, ledger=ledger, expected_recipient_peer_id="alice", expected_corr_id="wrong-corr", now_ms=int(time.time() * 1000))\n    assert ok3 is False and reason3 == "corr_id_mismatch"\n\n\ndef test_strict_hello_rejects_stale_proof() -> None:\n    ledger = _ledger()\n    alice = HandshakeState(config=_cfg("alice"))\n    hello = begin_outbound_handshake(alice)\n    ok, reason, *_ = verify_peer_hello_identity(hello=hello, ledger=ledger, strict=True, now_ms=int(hello.header.sent_ts_ms or 0) + 30_001, max_clock_skew_ms=30_000)\n    assert ok is False and reason == "stale_identity_proof"\n\n\ndef test_process_ack_rejects_wrong_corr_even_when_shape_is_otherwise_valid() -> None:\n    alice = HandshakeState(config=_cfg("alice"))\n    bob = HandshakeState(config=_cfg("bob"))\n    hello = begin_outbound_handshake(alice)\n    ack = process_inbound_hello(bob, hello)\n    bad = PeerHelloAck(header=type(ack.header)(type=ack.header.type, chain_id=ack.header.chain_id, schema_version=ack.header.schema_version, tx_index_hash=ack.header.tx_index_hash, sent_ts_ms=ack.header.sent_ts_ms, corr_id="wrong"), peer_id=ack.peer_id, ok=ack.ok, reason=ack.reason, caps=ack.caps, server_ts_ms=ack.server_ts_ms, phase=ack.phase, challenge=ack.challenge, recipient_peer_id=ack.recipient_peer_id, identity=ack.identity)\n    with pytest.raises(HandshakeRejected, match="hello_ack_corr_id_mismatch"):\n        process_inbound_ack(alice, bad)\n''')

